import java.util.ArrayList;
import java.util.List;

public class Main {
    static void fill(List<? super Integer> box, int howMany) {
        for (int i = 1; i <= howMany; i++) {
            box.add(i);
        }
    }

    public static void main(String[] args) {
        List<Object> box = new ArrayList<>();
        fill(box, 3);
        System.out.println("柜子里装了 " + box.size() + " 件");
        for (Object x : box) {
            System.out.println("装了 " + x);
        }
    }
}

